-- public.beast_mul(c creature, p_channel text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.beast_mul(c creature, p_channel text)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
  select trait_mul(c.traits, p_channel) * deed_aura(c, p_channel)
       -- And how deep its line runs (`line_mul`); nothing is looked up for one with no line past one on this channel.
       * case when c.pedigree is null or not coalesce(c.pedigree->'line' ? p_channel, false) then 1
              else line_mul(c.traits, c.pedigree->'line', p_channel) end
       -- And what its stage makes of it, for a kind that evolves (`evo_mul`).
       * evo_mul(c, p_channel)
       -- Ninety-nine in a hundred are ordinary, and the world tick asks this of every beast it moves: they are spared the look-up.
       * case when c.rare is null then 1 else rarity_blood(c.rare, p_channel) end
       -- And what ancient pots have put into its base stats (`pot_mul`); none at all on nearly everything.
       * case when c.boosts is null then 1 else pot_mul(c, p_channel) end
       * case when p_channel in ('work', 'learn') then care_mul(c) else 1 end
       -- And its size form (`form_mul`).
       * case when c.form_size is null then 1 else form_mul(c, p_channel) end
       -- And a lair's boss's (`lair_boss_mul`).
       * case when not c.boss then 1 else lair_boss_mul(c, p_channel) end
       -- And a good meal's learning, while it lasts (`beast_fed`).
       * case when p_channel = 'learn' and c.fed_until > now() then 1 + coalesce(c.fed_bonus, 0) else 1 end
       -- And a Sworn Blade's Hamstring, for as long as it holds (`slow`).
       * case when p_channel = 'speed' and c.slow_until > now() then coalesce(c.slow, 1) else 1 end
       -- And its keeper's Beastmaster passives while it follows them (`companionMul`): Thick Hide, Hardy Stock, Fleet and Quick Paws.
       * case when c.mode <> 'active' or c.kept is null then 1
              when p_channel = 'hardy' then coalesce((c.kept->>'kept:hardy')::double precision, 1)
              when p_channel = 'soak' then coalesce((c.kept->>'kept:soak')::double precision, 1)
              when p_channel = 'speed' then coalesce((c.kept->>'kept:speed')::double precision, 1)
              when p_channel = 'haste' then coalesce((c.kept->>'kept:haste')::double precision, 1)
              else 1 end
$function$
